-- ============================================================================
-- V22__sprint1_real_dev_seed.sql
--
-- Replaces the V17 fake/demo seed with the real wecmsvndev data extracted on
-- 2026-04-29 for tenant BIZ_KEY = 'VN_VNM0004_000001'. ~25 latest rows per
-- table where possible; tables empty in DEV keep their V17 stub data.
--
-- DELETE-then-INSERT approach: V17 seed used distinct synthetic PKs (e.g.
-- BANK_CD = 'BIDV') that don't exist in the real registry. The DELETE step
-- removes those rows so the endpoint payload is real-data-only.
--
-- Idempotent: DELETE is bounded to V17's BIZ_KEY + V17's specific synthetic
-- keys (so re-running doesn't wipe future user-edited rows) — but in
-- practice the V17 rows for this tenant are exactly the ones we want to
-- replace. INSERT uses ON CONFLICT DO NOTHING so re-runs are no-ops once
-- the real rows exist.
--
-- Tables empty in wecmsvndev for this tenant (kept as V17 stubs for demo):
--   BUSI_COND_DAILY_SUMR, BUSI_COND_DAILY_SUMR_DETL,
--   SELL_HIS_DAILY_SUMR, SELL_HIS_DAILY_SUMR_DETL,
--   ACCT_TRNS_RCV_PAY_EVID_FILE
-- ============================================================================

-- ============================================================================
-- 1. Clear V17 fake-seed rows for the Sprint 1 tenant.
-- ============================================================================
DELETE FROM ACCT_MSTR              WHERE BIZ_KEY='VN_VNM0004_000001' AND BANK_CD IN ('BIDV','WOORI','HDBANK','SHINHAN');
DELETE FROM ACCT_TRNS_HSTR         WHERE BIZ_KEY='VN_VNM0004_000001' AND ACCT_SEQ_NO LIKE 'TX%';
DELETE FROM ACCT_TRNS_RCV_PAY_INFM WHERE BIZ_KEY='VN_VNM0004_000001' AND ACCT_SEQ_NO LIKE 'TX%';
DELETE FROM NAPAS_REMIT_TRNS_HSTR  WHERE BIZ_KEY='VN_VNM0004_000001' AND SEQ_NO BETWEEN 1 AND 5 AND OUT_BANK_CODE IN ('BIDV','WOORI','HDBANK','SHINHAN');
DELETE FROM BUSA_DOC_MSTR          WHERE BIZ_KEY='VN_VNM0004_000001' AND DOC_ID LIKE 'EINV-%';
DELETE FROM OPRT_STTS_INFO         WHERE BIZ_KEY='VN_VNM0004_000001' AND TAXCODE IN ('0102345678','0103456789','0104567890','0105678901','0106789012');

-- ============================================================================
-- 2. ACCT_MSTR — 25 real rows from wecmsvndev (latest by acct_bal_upd_dtm).
-- ============================================================================
ON CONFLICT (BIZ_KEY, BANK_CD, ACCT_NO) DO NOTHING;

